<script setup lang="ts">
import {computed,h,onMounted,ref} from 'vue'
import {NConfigProvider,zhCN,dateZhCN} from 'naive-ui'
import AppProvider from './components/common/app-provider.vue'
import ConverterPanel from './ConverterPanel.vue'
import ReleasePanel from './ReleasePanel.vue'
const token=ref(sessionStorage.getItem('seal-admin-token')||''),password=ref(''),busy=ref(false),error=ref(''),section=ref('overview')
const mobileNavigation=ref(false)
const empty=()=>({users:[],publications:[],audit:[]})
const data=ref<any>(empty()),review=ref<any>(null),search=ref(''),statusFilter=ref('all'),actionFilter=ref('all'),updated=ref('')
let reviewEpoch=0
const options=[{label:'运行概览',key:'overview',description:'服务运行与空间使用情况'}, {label:'账号与用量',key:'users',description:'查看账号状态、注册时间与实际空间占用'}, {label:'演示模板审核',key:'template',description:'审核用户主动发布的演示模板'}, {label:'知识内容审核',key:'knowledge',description:'审核用户主动发布的知识资料'}, {label:'皮肤审核',key:'skin',description:'审核用户上传的界面皮肤，确认配色可读、无侵权后公开'}, {label:'操作记录',key:'audit',description:'查看云端操作与审核记录'}, {label:'文档转换',key:'converter',description:'管理手机兼容格式转换、访问令牌与任务状态'}, {label:'版本管理',key:'releases',description:'按版本维护更新说明，分别上传各平台附件；可只发布所需平台'}]
const current=computed(()=>options.find(o=>o.key===section.value)!)
const labels:Record<string,string>={pending:'待审核',approved:'已公开',rejected:'已拒绝',withdrawn:'已撤回'}
const statusOptions=[{label:'全部状态',value:'all'},...Object.entries(labels).map(([value,label])=>({value,label}))]
const actionLabels:Record<string,string>={'login':'登录云空间','enable-space':'开通云空间','purge-space':'清空并停用云空间','publish-request':'提交公开申请','public-report':'举报公开内容','review':'审核公开内容','review-download':'下载公开原文件','converter-config':'修改转换配置','converter-token-reset':'重置转换令牌','converter-test':'转换测试','release-create':'发布新版本','release-update':'修改发布','release-delete':'删除发布'}
actionLabels['release-asset-upload']='上传安装包'
const actionLabel=(value:any)=>actionLabels[String(value)]||String(value||'未知动作')
const pad=(value:number)=>String(value).padStart(2,'0')
const stamp=(value:any)=>{const time=Number(value);if(!time)return '—';const date=new Date(time);return Number.isNaN(date.getTime())?'—':`${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}`}
const shortId=(value:any)=>String(value||'').slice(0,8)
const accountOf=(value:any)=>value==='admin'?'管理员':(data.value.users.find((u:any)=>u.id===value)||{}).phone||String(value||'—')
function detailText(row:any){
  const raw=String(row.detail||'').trim(),action=String(row.action||'')
  if(!raw)return '—'
  try{
    if(action==='review'){const [id,status]=raw.split(':');return `公开内容 #${shortId(id)} · ${labels[status]||status||'已处理'}`}
    if(action==='review-download')return `公开原文件 #${shortId(raw)}`
    if(action==='publish-request')return `公开内容 #${shortId(raw)}`
    if(action==='public-report'){const [id,...rest]=raw.split(':');return `公开内容 #${shortId(id)} · ${rest.join(':')||'未填写理由'}`}
    if(action==='converter-config'){const config=JSON.parse(raw);return `${config.enabled?'启用':'暂停'} · 并发 ${config.concurrency}`}
    if(action==='converter-token-reset')return `令牌指纹 ${raw}`
    if(action==='converter-test')return raw==='passed'?'检查通过':'检查未通过'
    if(action.startsWith('release-')){const item=JSON.parse(raw);return [item.platform,item.version,item.channel==='beta'?'测试版':'稳定版',item.mandatory?'强制':'',item.withdrawn?'已下架':''].filter(Boolean).join(' · ')}
  }catch{return raw}
  return raw
}
function clearSession(){reviewEpoch++;token.value='';sessionStorage.removeItem('seal-admin-token');data.value=empty();review.value=null;updated.value=''}
async function call(route:string,method='GET',body?:unknown){const r=await fetch('/api/v1/admin/'+route,{method,headers:{'Content-Type':'application/json',...(token.value?{Authorization:'Bearer '+token.value}:{})},...(body?{body:JSON.stringify(body)}:{})});let result:any;try{result=await r.json()}catch{throw new Error('服务暂时无法响应，请稍后重试')}if(!r.ok){if(r.status===401)clearSession();throw new Error(result.error||'请求失败')}return result}
function uploadRelease(platform:string,version:string,file:File,progress:(value:number)=>void,signal:AbortSignal):Promise<any>{
  const owner=token.value
  return new Promise((resolve,reject)=>{
    if(signal.aborted){reject(new Error('安装包上传已取消'));return}
    const request=new XMLHttpRequest(),abort=()=>request.abort()
    request.open('POST','/api/v1/admin/release-assets?'+new URLSearchParams({platform,version,filename:file.name}))
    request.setRequestHeader('Authorization','Bearer '+owner)
    request.setRequestHeader('Content-Type','application/octet-stream')
    request.timeout=30*60*1000
    request.upload.onprogress=event=>{if(event.lengthComputable)progress(Math.min(99,Math.round(event.loaded/event.total*100)))}
    request.onload=()=>{
      if(request.status===401){clearSession();reject(new Error('管理员登录已过期，请重新登录后上传'));return}
      let result:any
      try{result=JSON.parse(request.responseText)}catch{reject(new Error(request.status===413?'安装包超过服务允许的大小，请联系管理员检查上传配置':'上传服务返回内容无效，请联系管理员检查后台部署'));return}
      if(request.status<200||request.status>=300){reject(new Error(result.error||'安装包上传失败'));return}
      if(owner!==token.value){reject(new Error('管理员会话已变更，请重新进入版本管理'));return}
      resolve(result)
    }
    request.onerror=()=>reject(new Error('安装包上传连接中断，请检查网络后重试'))
    request.ontimeout=()=>reject(new Error('安装包上传超时，请检查网络后重新上传'))
    request.onabort=()=>reject(new Error('安装包上传已取消'))
    request.onloadend=()=>signal.removeEventListener('abort',abort)
    signal.addEventListener('abort',abort,{once:true})
    request.send(file)
  })
}
async function run(task:()=>Promise<any>){if(busy.value)return;busy.value=true;error.value='';try{await task()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
async function load(){const owner=token.value;const result=await call('overview');if(owner!==token.value)return;data.value={...result,users:result.users.map((u:any)=>({...u,phone:String(u.phone||'').replace(/^(\d{3})\d{4}(\d{4})$/,'$1****$2')}))};updated.value=new Date().toLocaleTimeString('zh-CN',{hour12:false})}
async function login(){if(!password.value)return;await run(async()=>{const r=await call('login','POST',{username:'admin',password:password.value});password.value='';token.value=r.token;sessionStorage.setItem('seal-admin-token',r.token);await load()})}
async function logout(){await run(async()=>{await call('logout','POST');clearSession()})}
async function openReview(id:string){const request=++reviewEpoch,owner=token.value;await run(async()=>{const result=await call('publications/'+encodeURIComponent(id));if(request===reviewEpoch&&owner===token.value)review.value=result})}
async function downloadReview(){await run(async()=>{const r=await fetch('/api/v1/admin/publications/'+encodeURIComponent(review.value.id)+'/download',{headers:{Authorization:'Bearer '+token.value}});if(r.status===401){clearSession();throw new Error('登录已过期，请重新登录')}if(!r.ok)throw new Error('公开原文件下载失败');const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download=review.value.name||review.value.title;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)})}
async function decide(status:string){await run(async()=>{await call('publications/'+encodeURIComponent(review.value.id),'PATCH',{status});review.value=null;await load()})}
function navigate(key:string){reviewEpoch++;section.value=key;mobileNavigation.value=false;search.value='';statusFilter.value='all';actionFilter.value='all';review.value=null;error.value='';document.title=options.find(item=>item.key===key)?.label+' · 海豹办公管理后台'}
const publications=computed(()=>data.value.publications.filter((p:any)=>p.kind===section.value&&(statusFilter.value==='all'||p.status===statusFilter.value)&&[p.title,p.category,p.description].join(' ').toLowerCase().includes(search.value.trim().toLowerCase())))
const users=computed(()=>{const query=search.value.trim().toLowerCase();return query?data.value.users.filter((u:any)=>`${u.phone} ${u.id}`.toLowerCase().includes(query)):data.value.users})
const auditRows=computed(()=>{const query=search.value.trim().toLowerCase();return data.value.audit.filter((row:any)=>{if(actionFilter.value!=='all'&&row.action!==actionFilter.value)return false;return !query||[accountOf(row.user_id),row.user_id,actionLabel(row.action),row.action,row.detail,detailText(row),stamp(row.time)].join(' ').toLowerCase().includes(query)})})
const actionOptions=computed(()=>{const seen=new Map<string,string>();for(const row of data.value.audit)if(!seen.has(row.action))seen.set(row.action,actionLabel(row.action));return [{label:'全部动作',value:'all'},...[...seen].map(([value,label])=>({value,label})).sort((a,b)=>String(a.label).localeCompare(String(b.label),'zh-CN'))]})
const total=computed(()=>data.value.users.reduce((sum:number,u:any)=>sum+u.used,0))
const opened=computed(()=>data.value.users.filter((u:any)=>u.enabled).length)
const pending=computed(()=>data.value.publications.filter((p:any)=>p.status==='pending').length)
const userCount=computed(()=>search.value.trim()?`${users.value.length} / ${data.value.users.length} 个账号`:`${data.value.users.length} 个账号 · 已开通 ${opened.value}`)
const renderPill=(text:string,tone:string)=>h('span',{class:['pill',tone].filter(Boolean)},text)
const userColumns=[
  {title:'手机号',key:'phone',width:150,render:(u:any)=>h('span',{class:'num'},u.phone),sorter:(a:any,b:any)=>String(a.phone||'').localeCompare(String(b.phone||''))},
  {title:'账号标识',key:'id',width:200,ellipsis:{tooltip:true},render:(u:any)=>h('span',{class:'cell-id'},u.id)},
  {title:'云空间',key:'enabled',width:104,render:(u:any)=>renderPill(u.enabled?'已开通':'关闭',u.enabled?'ok':'')},
  {title:'自动保存',key:'autosave',width:104,render:(u:any)=>renderPill(u.autosave?'开启':'关闭',u.autosave?'ok':'')},
  {title:'注册时间',key:'created',width:164,sorter:(a:any,b:any)=>(Number(a.created)||0)-(Number(b.created)||0),render:(u:any)=>h('span',{class:'stamp'},stamp(u.created))},
  {title:'最后一次操作时间',key:'lastAction',width:184,sorter:(a:any,b:any)=>(Number(a.lastAction)||0)-(Number(b.lastAction)||0),defaultSortOrder:'descend',render:(u:any)=>h('span',{class:u.lastAction?'stamp':'stamp muted'},stamp(u.lastAction))},
  {title:'实际占用',key:'used',width:120,align:'right',sorter:(a:any,b:any)=>(Number(a.used)||0)-(Number(b.used)||0),render:(u:any)=>h('span',{class:'num'},(Number(u.used||0)/1000000).toFixed(2)+' MB')}
]
const auditColumns=[
  {title:'时间',key:'time',width:170,defaultSortOrder:'descend',sorter:(a:any,b:any)=>(Number(a.time)||0)-(Number(b.time)||0),render:(row:any)=>h('span',{class:'stamp'},stamp(row.time))},
  {title:'操作账号',key:'user_id',width:190,render:(row:any)=>row.user_id==='admin'?h('span',{class:'cell-admin'},'管理员'):h('span',{class:'num'},accountOf(row.user_id))},
  {title:'动作',key:'action',width:168,render:(row:any)=>actionLabel(row.action)},
  {title:'记录',key:'detail',ellipsis:{tooltip:true},render:(row:any)=>detailText(row)}
]
const theme={common:{primaryColor:'#1e5eff',primaryColorHover:'#3972ff',primaryColorPressed:'#184bd1',borderRadius:'4px',fontSize:'13px',heightMedium:'32px',fontFamily:'"Segoe UI", "Microsoft YaHei", sans-serif'},Button:{fontWeight:'500',borderRadiusMedium:'3px',borderRadiusSmall:'3px',heightMedium:'32px',heightSmall:'28px'},Card:{titleFontWeight:'600',titleFontSizeMedium:'14px',paddingMedium:'16px',borderRadius:'4px',borderColor:'#e2e6ec'},DataTable:{thColor:'#fafbfc',thTextColor:'#4f5e72',thFontWeight:'500',tdColor:'#ffffff',tdColorHover:'#f7f9fc',tdTextColor:'#44536a',borderColor:'#e7eaf0',fontSizeMedium:'13px',fontSizeSmall:'13px',tdPaddingMedium:'9px 12px',thPaddingMedium:'9px 12px',tdPaddingSmall:'8px 12px',thPaddingSmall:'9px 12px'},Input:{borderRadius:'3px'},InternalSelection:{borderRadius:'3px'},Tag:{borderRadius:'3px'},Pagination:{itemBorderRadius:'3px'}}
onMounted(()=>{if(token.value)void run(load)})
</script>
<template>
  <NConfigProvider :locale="zhCN" :date-locale="dateZhCN" :theme-overrides="theme"><AppProvider>
    <main v-if="!token" class="login-page">
      <header class="login-story"><div class="login-brand"><img src="/seal-logo.png" alt="海豹办公标志"/><span>海豹办公<strong>云端管理控制台</strong></span></div></header>
      <section class="login-form-area"><div class="login-form"><span class="eyebrow">管理员工作台</span><h2>欢迎回来</h2><p class="form-intro">登录以查看服务状态及处理公开内容审核。</p><form @submit.prevent="login"><label for="admin-name">管理员账号</label><NInput id="admin-name" value="admin" readonly size="large" autocomplete="username"/><label for="admin-password">登录密码</label><NInput id="admin-password" v-model:value="password" type="password" show-password-on="click" placeholder="请输入管理员密码" size="large" autocomplete="current-password"/><NAlert v-if="error" type="error" class="login-error">{{error}}</NAlert><NButton attr-type="submit" type="primary" size="large" block :loading="busy" :disabled="!password||busy" class="login-submit">登录管理后台</NButton></form><p class="login-footnote">仅供授权管理员使用。私有云文档不提供解密入口。</p></div><span class="login-copyright">海豹办公云端服务</span></section>
    </main>
    <div v-else class="admin-shell">
      <header class="topbar"><div class="sidebar-brand"><img src="/seal-logo.png" alt="海豹办公标志"/><strong>海豹办公</strong><span>云端管理</span></div><button class="navigation-toggle" type="button" :aria-expanded="mobileNavigation" aria-controls="management-navigation" @click="mobileNavigation=!mobileNavigation">菜单</button><div class="topbar-actions"><span>管理员</span><NButton quaternary :disabled="busy" @click="logout">退出登录</NButton></div></header>
      <aside id="management-navigation" class="sidebar" :class="{'is-open':mobileNavigation}" @keydown.esc="mobileNavigation=false"><nav aria-label="管理导航"><button v-for="(item,index) in options" :key="item.key" class="nav-item" :class="{active:section===item.key}" :aria-current="section===item.key?'page':undefined" @click="navigate(item.key)"><span class="nav-index">{{String(index+1).padStart(2,'0')}}</span>{{item.label}}<span v-if="item.key==='overview'&&pending" class="nav-count">{{pending}}</span></button></nav><div class="sidebar-note"><strong>私有资料保持加密</strong><p>仅审核用户主动发布的公开资料。</p></div></aside>
      <div class="workspace">
        <main class="workspace-content"><div v-if="section!=='releases'" class="page-heading"><div><h1>{{current.label}}</h1><p>{{current.description}}</p></div><div v-if="section!=='converter'&&section!=='releases'" class="refresh-area"><span v-if="updated">更新于 {{updated}}</span><NButton :loading="busy" @click="run(load)">刷新数据</NButton></div></div><NAlert v-if="error" type="error" class="page-error">{{error}}</NAlert>
          <template v-if="section==='overview'"><div class="stats-grid"><div class="stat-card"><span>账号总数</span><strong>{{data.users.length}}<small>个</small></strong><p>已注册的海豹办公账号</p></div><div class="stat-card"><span>实际文件占用</span><strong>{{(total/1000000).toFixed(2)}}<small>MB</small></strong><p>包含历史版本与回收站</p></div><div class="stat-card"><span>等待审核</span><strong>{{pending}}<small>项</small></strong><p>演示模板、知识与皮肤公开申请</p></div></div>
            <div class="overview-grid"><NCard title="云服务运行"><template #header-extra><NTag :type="data.runtime?'success':'default'" round>{{data.runtime?'已连接':'等待数据'}}</NTag></template><div class="service-metrics"><div><span>服务器剩余磁盘</span><strong>{{((data.runtime?.diskFree||0)/1000000000).toFixed(2)}}<small>GB</small></strong></div><div><span>进程内存</span><strong>{{((data.runtime?.memory||0)/1000000).toFixed(0)}}<small>MB</small></strong></div><div><span>待提交上传</span><strong>{{data.runtime?.pendingUploads||0}}<small>项</small></strong></div><div><span>每账号实际配额</span><strong>{{((data.quota||300000000)/1000000).toFixed(0)}}<small>MB</small></strong></div></div><div class="privacy-note"><strong>客户端加密保护</strong><p>私有文件名、正文与资料索引以密文保存，管理员无法在此工作台打开私有文档。</p></div></NCard><NCard title="短信服务"><template #header-extra><NTag :type="data.smsConfigured?'success':'warning'" round>{{data.smsConfigured?'已配置':'未配置'}}</NTag></template><dl class="detail-list"><div><dt>短信签名</dt><dd>{{data.sms?.sign||'未设置'}}</dd></div><div><dt>验证码模板</dt><dd>{{data.sms?.template||'未设置'}}</dd></div><div><dt>24 小时发送请求</dt><dd>{{data.sms?.lastDay||0}} 次</dd></div></dl><p class="service-note">配置状态仅表示服务接入情况，实际送达取决于运营商报备与短信发送结果。</p></NCard></div>
          </template>
          <NCard v-else-if="section==='users'" title="账号列表"><template #header-extra><span class="table-count">{{userCount}}</span></template><div class="list-toolbar"><NInput v-model:value="search" clearable placeholder="搜索号码前3位、后4位或账号标识" class="table-search"/><span class="toolbar-hint">按最后一次操作时间倒序 · 点击表头切换排序</span></div><NDataTable :columns="userColumns" :data="users" :pagination="{pageSize:20}" :scroll-x="1080" :loading="busy"/></NCard>
          <NCard v-else-if="section==='audit'" title="最近操作记录"><template #header-extra><span class="table-count">{{auditRows.length}} / {{data.audit.length}} 条记录</span></template><div class="list-toolbar"><NInput v-model:value="search" clearable placeholder="搜索号码片段、操作类型或记录内容" class="table-search"/><NSelect v-model:value="actionFilter" :options="actionOptions" class="table-select"/><span class="toolbar-hint">仅保留最近 200 条记录</span></div><NDataTable :columns="auditColumns" :data="auditRows" :pagination="{pageSize:20}" :scroll-x="900" :loading="busy"/></NCard>
          <ConverterPanel v-else-if="section==='converter'" :call="call"/>
          <ReleasePanel v-else-if="section==='releases'" :call="call" :upload="uploadRelease"/>
          <template v-else><div class="list-toolbar"><NInput v-model:value="search" clearable placeholder="搜索标题、分类或说明" class="table-search"/><NSelect v-model:value="statusFilter" :options="statusOptions" class="table-select"/><span class="toolbar-hint">{{publications.length}} 项内容</span></div><NEmpty v-if="!publications.length" class="empty-state" :description="search||statusFilter!=='all'?'没有匹配的公开内容':'暂无公开内容申请'"/><div v-else class="publications-grid"><NCard v-for="p in publications" :key="p.id" class="publication-card"><div class="publication-cover"><img v-if="p.cover" :src="p.cover" alt="公开封面"/><div v-else class="cover-placeholder">{{section==='template'?'演示模板':section==='skin'?'界面皮肤':'知识资料'}}</div><span class="status-pill" :class="p.status">{{labels[p.status]||p.status}}</span></div><div class="publication-body"><span class="publication-category">{{p.category||'未分类'}}</span><h2>{{p.title}}</h2><NButton block :disabled="busy" @click="openReview(p.id)">查看资料并审核</NButton></div></NCard></div></template>
        </main><footer class="workspace-footer">海豹办公 · 云端管理控制台</footer>
      </div>
    </div>
    <NModal :show="Boolean(review)" @update:show="value=>{if(!value)review=null}" preset="card" title="公开内容审核" class="review-modal" :mask-closable="false" @close="review=null"><template v-if="review"><div class="review-heading"><h2>{{review.title}}</h2><NTag>{{labels[review.status]||review.status}}</NTag></div><p class="review-intro">仅显示用户主动发布的公开资料。请检查原文件后决定是否发布。</p><NButton :loading="busy" :disabled="review.status==='withdrawn'" @click="downloadReview">下载公开原文件检查</NButton><pre>{{review.text||'暂无文字预览，请下载公开文件检查。'}}</pre><NAlert v-if="error" type="error">{{error}}</NAlert><div class="review-actions"><NButton type="primary" :loading="busy" :disabled="review.status==='withdrawn'||review.status==='approved'" @click="decide('approved')">通过并公开</NButton><NButton type="warning" :disabled="busy||review.status==='withdrawn'||review.status==='rejected'" @click="decide('rejected')">拒绝发布</NButton><NButton type="error" :disabled="busy||review.status==='withdrawn'" @click="decide('withdrawn')">下架</NButton></div></template></NModal>
  </AppProvider></NConfigProvider>
</template>
<style>
*{box-sizing:border-box}body{margin:0;font-family:'Segoe UI','Microsoft YaHei',sans-serif;font-size:13px;color:#34445a;background:#f4f6f9}button,input{font:inherit}button{cursor:pointer}.num,.stamp,.table-count{font-variant-numeric:tabular-nums}.stamp.muted{color:#7b8796}.cell-id{font-family:Consolas,monospace;font-size:12px;color:#637086}.cell-admin{color:#2458a9;font-weight:600}.eyebrow{font-size:12px;color:#66758a}.pill{display:inline-flex;align-items:center;min-height:22px;padding:1px 7px;border-radius:3px;font-size:12px;line-height:1.5;background:#eef1f5;color:#617087}.pill.ok{background:#e7f5ef;color:#28745c}.pill.warn{background:#fff4df;color:#8b621c}.pill.bad{background:#fceced;color:#b34851}
/* 顶栏与侧栏采用统一的紧凑后台框架。 */
.admin-shell{min-height:100vh;min-height:100dvh;padding-top:60px}.topbar{position:fixed;inset:0 0 auto;height:60px;display:flex;align-items:center;background:#23292e;color:#fff;z-index:20;padding:0 20px}.sidebar-brand{display:flex;align-items:center;gap:10px;min-width:180px}.sidebar-brand img{width:32px;height:32px}.sidebar-brand strong{font-size:16px;font-weight:600;white-space:nowrap}.sidebar-brand>span{font-size:12px;color:#b9c2cb;margin-left:4px}.topbar-actions{display:flex;align-items:center;gap:16px;margin-left:auto;font-size:13px;color:#c7cfd7}.topbar .n-button{color:#c7cfd7}.topbar .n-button:hover{color:#fff;background:#ffffff12}.navigation-toggle{display:none;border:1px solid #56616b;border-radius:3px;background:transparent;color:#fff;min-height:32px;padding:4px 10px;margin-left:14px}.sidebar{position:fixed;inset:60px auto 0 0;display:flex;flex-direction:column;width:200px;background:#2d343a;color:#fff;z-index:10;padding:10px 0;overflow-y:auto}.nav-item{display:flex;align-items:center;gap:10px;width:100%;border:0;background:transparent;color:#c5ced8;text-align:left;padding:12px 18px;min-height:44px;border-radius:0;margin:0;cursor:pointer;font-size:14px;transition:background .15s,color .15s}.nav-item:hover{background:#3a444d;color:#fff}.nav-item.active{background:#1e5eff;color:#fff;font-weight:500}.nav-item:focus-visible,.navigation-toggle:focus-visible{outline:2px solid #a8c8ff;outline-offset:-3px}.nav-index{font-size:11px;color:inherit;opacity:.8;font-variant-numeric:tabular-nums}.nav-count{margin-left:auto;border-radius:3px;background:#ffffff24;padding:1px 5px;font-size:11px}.sidebar-note{margin-top:auto;padding:20px 18px 8px;font-size:12px;color:#bdc7d2}.sidebar-note strong{font-weight:500}.sidebar-note p{line-height:1.7;color:#a4b0bd;font-size:11px;margin:8px 0 0}.workspace{display:flex;flex-direction:column;min-width:0;min-height:calc(100vh - 60px);margin-left:200px}.workspace-content{padding:18px 20px 24px;width:100%;min-width:0;flex:1}.page-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:16px}.page-heading h1{font-size:18px;font-weight:600;margin:0 0 7px;line-height:1.4;color:#21324a}.page-heading p{font-size:13px;color:#68788e;margin:0;line-height:1.6}.refresh-area{display:flex;align-items:center;gap:12px}.refresh-area>span{font-size:12px;color:#6c7b8c}.page-error{margin-bottom:16px}.workspace-footer{padding:0 20px 16px;font-size:11px;color:#6e7d91}
/* 登录沿用相同顶栏和表单密度，不放置额外宣传区域。 */
.login-page{min-height:100vh;min-height:100dvh;background:#f4f6f9;padding-top:60px}.login-story{position:absolute;inset:0 0 auto;height:60px;padding:0 20px;background:#23292e;color:#fff;display:flex;align-items:center}.login-brand{display:flex;align-items:center;gap:10px;font-size:16px;font-weight:600}.login-brand img{width:32px;height:32px}.login-brand strong{display:inline;margin-left:16px;font-size:12px;font-weight:400;color:#bac4cf}.login-form-area{display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:calc(100vh - 60px);padding:40px 20px;gap:24px}.login-form{width:100%;max-width:420px;padding:28px;border:1px solid #e1e6ee;border-radius:4px;background:#fff;box-shadow:0 2px 8px #182a3d08}.login-form h2{font-size:22px;font-weight:600;margin:8px 0 10px;color:#24344a}.form-intro{font-size:13px;line-height:1.8;color:#68788e;margin:0 0 18px}.login-form label{display:block;font-size:13px;font-weight:500;margin:16px 0 8px}.login-form .n-input{min-height:38px}.login-error{margin-top:14px}.login-submit{margin-top:22px;height:38px}.login-footnote{font-size:12px;line-height:1.7;color:#67768b;margin:18px 0 0}.login-copyright{font-size:12px;color:#738195}
/* 概览、转换与资料列表共享卡片边界和字号。 */
.stats-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.stat-card{padding:16px 18px;border:1px solid #e2e6ec;border-radius:4px;background:#fff;min-width:0}.stat-card>span{font-size:13px;color:#627187}.stat-card>strong{display:block;font-size:28px;font-weight:600;line-height:1.4;margin-top:8px;font-variant-numeric:tabular-nums;color:#27394f}.stat-card small{font-size:12px;font-weight:400;color:#738297;margin-left:8px}.stat-card p{font-size:12px;color:#6d7c91;margin:6px 0 0;line-height:1.6}.overview-grid{display:grid;grid-template-columns:1.4fr 1fr;gap:14px;margin-top:16px}.overview-grid>.n-card{min-width:0}.service-metrics{display:grid;grid-template-columns:1fr 1fr;gap:18px;padding:0 0 16px}.service-metrics span{display:block;color:#6d7c91;font-size:12px}.service-metrics strong{display:block;font-size:22px;font-weight:600;margin-top:7px;font-variant-numeric:tabular-nums}.service-metrics small{font-size:12px;font-weight:400;color:#6d7c91;margin-left:6px}.privacy-note{border-radius:4px;background:#f2f5fa;padding:12px 14px;font-size:12px}.privacy-note strong{color:#2458a9}.privacy-note p{line-height:1.7;color:#62758e;margin:6px 0 0}.detail-list{margin:0}.detail-list>div{padding:12px 0;border-bottom:1px solid #e8ecf2}.detail-list dt{font-size:12px;color:#69798e}.detail-list dd{margin:6px 0 0;font-size:13px;color:#44546b;overflow-wrap:anywhere}.service-note{color:#67768a;font-size:12px;line-height:1.7;margin:14px 0 0}.list-toolbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:14px}.table-search{max-width:340px;flex:1 1 240px}.table-select{width:160px}.toolbar-hint{margin-left:auto;font-size:12px;color:#6b7a8f}.table-count{font-size:12px;color:#6b7a8f}.empty-state{padding:60px 20px;background:#fff;border:1px solid #e2e6ec;border-radius:4px}.publications-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(260px,100%),1fr));gap:14px}.publication-card{overflow:hidden}.publication-card>.n-card__content{padding:0!important}.publication-cover{position:relative;height:148px;background:#edf1f6}.publication-cover img{width:100%;height:100%;object-fit:cover}.cover-placeholder{display:grid;place-items:center;height:100%;font-size:18px;font-weight:500;color:#647a99;background:#edf2f8}.status-pill{position:absolute;top:10px;right:10px;font-size:12px;border-radius:3px;padding:3px 7px;background:#fff;color:#627187}.status-pill.pending{color:#8b621c;background:#fff4df}.status-pill.approved{color:#28745c;background:#e7f5ef}.status-pill.rejected{color:#b34851;background:#fceced}.publication-body{padding:14px}.publication-category{font-size:12px;color:#6d7c91}.publication-body h2{font-size:15px;font-weight:600;line-height:1.5;margin:6px 0 14px;overflow-wrap:anywhere}
.review-modal{width:800px;max-width:95vw;max-height:90vh;max-height:90dvh}.review-modal>.n-card__content{overflow:auto}.review-heading{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.review-heading h2{font-size:18px;margin:0;overflow-wrap:anywhere}.review-intro{font-size:13px;color:#68788e;line-height:1.7}.review-actions{display:flex;justify-content:flex-end;gap:10px;flex-wrap:wrap;margin-top:16px}pre{white-space:pre-wrap;max-height:45vh;overflow:auto;font:13px/1.8 'Segoe UI','Microsoft YaHei',sans-serif;padding:14px;background:#f4f6fa;border-radius:4px;overflow-wrap:anywhere;margin:16px 0}
@media(max-width:1100px){.overview-grid{grid-template-columns:1fr}}
@media(max-width:760px){.topbar{padding:0 14px}.sidebar-brand{min-width:0;gap:8px}.sidebar-brand>span{display:none}.sidebar-brand strong{font-size:14px}.topbar-actions{gap:8px}.topbar-actions>span{display:none}.navigation-toggle{display:block;margin-left:12px}.sidebar{display:none;position:static;width:auto;max-height:50vh;padding:6px 0}.sidebar.is-open{display:block}.sidebar nav{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.sidebar-note{display:none}.nav-item{font-size:13px;padding:12px 14px}.workspace{margin-left:0}.workspace-content{padding:16px}.page-heading{align-items:flex-start;gap:12px}.refresh-area>span{display:none}.stats-grid{grid-template-columns:1fr;gap:12px}.list-toolbar{align-items:flex-start}.table-search{max-width:none;flex-basis:100%}.toolbar-hint{margin-left:0}.workspace-footer{padding:0 16px 16px}.login-brand strong{margin-left:10px}.login-form{padding:24px}.login-form-area{padding:24px 16px}.n-button{min-height:32px}.n-base-close{min-width:32px;min-height:32px}}
@media(pointer:coarse){.navigation-toggle,.nav-item,.n-button{min-height:40px}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;transition:none!important;animation:none!important}}
</style>
